<style lang="scss" scoped src="./breadcrumb.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../../components/icon/icon.vue";
import { IconShape } from "../../components/icon/icon.constants";

@Component({
  components: {
    Icon
  }
})
export default class Breadcrumb extends Vue {
  /**
    {
      label: string,
      mode: BreadcrumbMode,
      addition?: {
        label: string,
        value: string
      },
      copy: boolean
    }
   */
  @Prop({
    type: Array,
    default: () => []
  })
  values;

  @Prop({
    type: Number,
    default: IconShape.ACCOUNTING_THIN
  })
  icon;

  IconShape = IconShape;

  modeToClass(mode) {
    return mode;
  }

  handleCopy(index) {
    try {
      const el = document.createElement("textarea");
      el.value = this.$refs[`value_${index}`][0].innerText;
      el.setAttribute("readonly", "");
      el.style.position = "absolute";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
    } catch (err) {
      // Could not copy
    }
  }
}
</script>

<template>
  <div class="Breadcrumb">
    <div class="Breadcrumb__Icon">
      <Icon :shape="icon" :size="25" :color="'#DADCE8'" />
    </div>
    <div v-for="(value, i) in values" class="Breadcrumb__Crumb" :key="i">
      <div v-if="i > 0" class="Breadcrumb__Arrow">→</div>
      <div :class="['Breadcrumb__Label', modeToClass(value.mode)]">
        {{ value.label }}
      </div>
      <div v-if="value.addition" class="Breadcrumb__Addition">
        <div class="Breadcrumb__AdditionLabel">{{ value.addition.label }}</div>
        <div class="Breadcrumb__AdditionValue" :ref="`value_${i}`">
          {{ value.addition.value }}
        </div>
      </div>
      <div v-if="value.copy" class="Breadcrumb__Copy" @click="handleCopy(i)">
        <Icon :shape="IconShape.COPY" :size="16" :color="'#2356f6'" />
      </div>
    </div>
  </div>
</template>
